-- Generated by scripts/render_athena.py. Do not edit by hand: change the schemas or sql/gold/ and re-run.
-- Athena runs one statement at a time; statements are separated by a line containing only ";".
-- Bucket: <CURATED_BUCKET>

DROP TABLE IF EXISTS vitalstream_gold.a1c_trend
;

CREATE TABLE vitalstream_gold.a1c_trend
WITH (
    format = 'PARQUET',
    write_compression = 'SNAPPY',
    external_location = 's3://<CURATED_BUCKET>/gold/a1c_trend/',
    partitioned_by = ARRAY['result_year']
)
AS
-- Every HbA1c result with the previous result, change, 3-test rolling average and clinical band.
-- partitioned_by: result_year
-- Skills: ROW_NUMBER(), LAG(), moving AVG() over a window frame, partitioning by event date.
-- Bands (ADA): normal < 5.7%, prediabetes 5.7-6.4%, diabetes >= 6.5%.
SELECT
    patient_id,
    observation_id,
    effective_at,
    value_num AS a1c_pct,
    row_number() OVER (PARTITION BY patient_id ORDER BY effective_at) AS test_number,
    lag(value_num) OVER (PARTITION BY patient_id ORDER BY effective_at) AS previous_a1c_pct,
    round(value_num - lag(value_num) OVER (PARTITION BY patient_id ORDER BY effective_at), 2)
        AS change_pct_points,
    round(avg(value_num) OVER (
        PARTITION BY patient_id
        ORDER BY effective_at
        ROWS BETWEEN 2 PRECEDING AND CURRENT ROW
    ), 2) AS rolling_avg_3,
    CASE
        WHEN value_num >= 6.5 THEN 'diabetes'
        WHEN value_num >= 5.7 THEN 'prediabetes'
        ELSE 'normal'
    END AS a1c_band,
    CAST(extract(year FROM effective_at) AS INTEGER) AS result_year   -- partition column: must be last
FROM vitalstream_silver.observations
WHERE code = '4548-4'   -- LOINC: Hemoglobin A1c
;

DROP TABLE IF EXISTS vitalstream_gold.condition_prevalence
;

CREATE TABLE vitalstream_gold.condition_prevalence
WITH (
    format = 'PARQUET',
    write_compression = 'SNAPPY',
    external_location = 's3://<CURATED_BUCKET>/gold/condition_prevalence/'
)
AS
-- How common each disorder is: patients ever and currently affected, % of all patients, and rank.
-- partitioned_by: none
-- Skills: COUNT(DISTINCT), CROSS JOIN to a total, safe division, DENSE_RANK().
WITH population AS (
    SELECT count(*) AS total_patients
    FROM vitalstream_silver.patients
),

per_condition AS (
    SELECT
        code,
        max(code_display) AS condition,
        count(DISTINCT patient_id) AS patients_ever,
        count(DISTINCT patient_id) FILTER (WHERE clinical_status = 'active') AS patients_active
    FROM vitalstream_silver.conditions
    WHERE semantic_tag = 'disorder'   -- skip findings like "Full-time employment"
    GROUP BY code
)

SELECT
    c.code,
    c.condition,
    c.patients_ever,
    c.patients_active,
    -- CAST to DOUBLE: in Athena, integer / integer drops the decimals
    round(100 * CAST(c.patients_ever AS DOUBLE) / p.total_patients, 1) AS pct_ever,
    round(100 * CAST(c.patients_active AS DOUBLE) / p.total_patients, 1) AS pct_active,
    dense_rank() OVER (ORDER BY c.patients_ever DESC) AS rank_ever,
    dense_rank() OVER (ORDER BY c.patients_active DESC) AS rank_active
FROM per_condition c
CROSS JOIN population p
;

DROP TABLE IF EXISTS vitalstream_gold.encounters_monthly
;

CREATE TABLE vitalstream_gold.encounters_monthly
WITH (
    format = 'PARQUET',
    write_compression = 'SNAPPY',
    external_location = 's3://<CURATED_BUCKET>/gold/encounters_monthly/'
)
AS
-- Visits per month and visit class, with change vs the previous month and a year-to-date total.
-- partitioned_by: none
-- Skills: date_trunc, GROUP BY, LAG() and running SUM() window functions.
WITH snapshot AS (
    SELECT max(start_at) AS as_of
    FROM vitalstream_silver.encounters
),

monthly AS (
    SELECT
        CAST(date_trunc('month', e.start_at) AS DATE) AS month,
        e.class_code,
        count(*) AS encounters,
        count(DISTINCT e.patient_id) AS patients,
        round(avg(CAST(date_diff('second', e.start_at, e.end_at) AS DOUBLE)) / 60, 1) AS avg_duration_min
    FROM vitalstream_silver.encounters e
    CROSS JOIN snapshot s
    -- Last 10 years; older visits are sparse carry-overs from long-running conditions
    WHERE e.start_at >= s.as_of - INTERVAL '10' YEAR
    GROUP BY CAST(date_trunc('month', e.start_at) AS DATE), e.class_code
)

SELECT
    month,
    class_code,
    encounters,
    patients,
    avg_duration_min,
    -- Compared with the previous month that had visits of this class
    encounters - lag(encounters) OVER (PARTITION BY class_code ORDER BY month) AS change_vs_prev_month,
    CAST(sum(encounters) OVER (
        PARTITION BY class_code, extract(year FROM month)
        ORDER BY month
        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
    ) AS BIGINT) AS ytd_encounters
FROM monthly
;

DROP TABLE IF EXISTS vitalstream_gold.patient_summary
;

CREATE TABLE vitalstream_gold.patient_summary
WITH (
    format = 'PARQUET',
    write_compression = 'SNAPPY',
    external_location = 's3://<CURATED_BUCKET>/gold/patient_summary/'
)
AS
-- One row per patient: demographics, visits, chronic conditions and latest vitals.
-- partitioned_by: none
-- Skills: CTEs, LEFT JOINs, GROUP BY with FILTER, ROW_NUMBER() to pick the latest reading.
WITH snapshot AS (
    -- "Today" for this dataset = the latest visit date, so results don't drift with the calendar
    SELECT max(CAST(start_at AS DATE)) AS as_of
    FROM vitalstream_silver.encounters
),

people AS (
    SELECT
        p.patient_id,
        p.gender,
        p.race,
        p.ethnicity,
        p.birth_date,
        p.deceased_at,
        coalesce(CAST(p.deceased_at AS DATE), s.as_of) AS age_date
    FROM vitalstream_silver.patients p
    CROSS JOIN snapshot s
),

visits AS (
    SELECT
        patient_id,
        count(*) AS encounter_count,
        count(*) FILTER (WHERE class_code = 'EMER') AS emergency_visits,
        count(*) FILTER (WHERE class_code = 'IMP') AS inpatient_stays,
        min(start_at) AS first_encounter_at,
        max(start_at) AS last_encounter_at
    FROM vitalstream_silver.encounters
    GROUP BY patient_id
),

diagnoses AS (
    SELECT
        patient_id,
        count(DISTINCT code) FILTER (WHERE clinical_status = 'active' AND semantic_tag = 'disorder')
            AS active_disorders,
        bool_or(code = '44054006') AS has_diabetes,       -- Diabetes mellitus type 2
        bool_or(code = '714628002') AS has_prediabetes,   -- Prediabetes
        bool_or(code = '59621000') AS has_hypertension    -- Essential hypertension
    FROM vitalstream_silver.conditions
    GROUP BY patient_id
),

latest_vitals AS (
    -- Rank each patient's readings of each vital, newest first, and keep rank 1
    SELECT
        patient_id,
        max(value_num) FILTER (WHERE code = '8480-6') AS latest_systolic,
        max(value_num) FILTER (WHERE code = '8462-4') AS latest_diastolic,
        max(value_num) FILTER (WHERE code = '39156-5') AS latest_bmi
    FROM (
        SELECT
            patient_id,
            code,
            value_num,
            row_number() OVER (PARTITION BY patient_id, code ORDER BY effective_at DESC) AS rn
        FROM vitalstream_silver.observations
        WHERE code IN ('8480-6', '8462-4', '39156-5')
    ) ranked
    WHERE rn = 1
    GROUP BY patient_id
),

aged AS (
    -- Whole years between birth and age_date (subtract 1 if the birthday hasn't come yet)
    SELECT
        *,
        extract(year FROM age_date) - extract(year FROM birth_date)
            - CASE WHEN extract(month FROM age_date) * 100 + extract(day FROM age_date)
                      < extract(month FROM birth_date) * 100 + extract(day FROM birth_date)
                   THEN 1 ELSE 0 END AS age_years
    FROM people
)

SELECT
    a.patient_id,
    a.gender,
    a.race,
    a.ethnicity,
    a.birth_date,
    a.age_years,
    CASE
        WHEN a.age_years < 18 THEN '0-17'
        WHEN a.age_years < 40 THEN '18-39'
        WHEN a.age_years < 65 THEN '40-64'
        ELSE '65+'
    END AS age_group,
    a.deceased_at IS NOT NULL AS is_deceased,
    coalesce(v.encounter_count, 0) AS encounter_count,
    coalesce(v.emergency_visits, 0) AS emergency_visits,
    coalesce(v.inpatient_stays, 0) AS inpatient_stays,
    v.first_encounter_at,
    v.last_encounter_at,
    coalesce(d.active_disorders, 0) AS active_disorders,
    coalesce(d.has_diabetes, false) AS has_diabetes,
    coalesce(d.has_prediabetes, false) AS has_prediabetes,
    coalesce(d.has_hypertension, false) AS has_hypertension,
    lv.latest_systolic,
    lv.latest_diastolic,
    lv.latest_bmi
FROM aged a
LEFT JOIN visits v ON v.patient_id = a.patient_id
LEFT JOIN diagnoses d ON d.patient_id = a.patient_id
LEFT JOIN latest_vitals lv ON lv.patient_id = a.patient_id
;
